/**
 * Generated content and placeholder helpers for scaffold installs.
 */

/**
 * Composer requires `vendor/package`, both lowercase and matching
 * ^[a-z0-9]([_.-]?[a-z0-9]+)*$ per segment. A bare project name fails
 * validation, so `composer install` errors out on a freshly generated
 * project. Vendor defaults to `app` because the scaffold does not collect an
 * organization slug; the generated file is a starter the team renames.
 */
export function toComposerPackageName(projectName, vendor = 'app') {
  const slug = String(projectName ?? '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');
  return `${vendor}/${slug || 'project'}`;
}

export function resolvePlaceholders(content, values) {
  const tokenMap = {
    '{{PROJECT_NAME}}': values.projectName ?? '',
    '{{COMPOSER_PACKAGE_NAME}}': toComposerPackageName(values.projectName),
    '{{PROJECT_DISPLAY_NAME}}': values.displayName ?? '',
    '{{PROJECT_DESCRIPTION}}': values.purpose ?? '',
    '{{ONE_LINE_PURPOSE}}': values.purpose ?? '',
    '{{SaaS / Internal Tool / API / Platform}}': values.projectType ?? '',
    '{{Active Development / MVP / Production}}': 'Active Development',
    '{{IS_MULTI_TENANT}}': String(values.multiTenant ?? false),
    '{{COMPLIANCE_SCOPE}}': formatCompliance(values.complianceScope),
    '{{OWNER_EMAIL}}': values.ownerEmail ?? '',
    '{{EPIC_NAME}}': values.purpose ?? '',
    '{{BACKEND_STACK}}': values.backendStack ?? 'N/A',
    '{{FRONTEND_STACK}}': values.frontendStack ?? 'none',
    '{{DATABASE}}': values.database ?? 'N/A',
    '{{RUNTIME}}': values.backendStack ?? 'N/A',
    '{{REPO_URL}}': 'N/A',
    '{{INSTALL_COMMAND}}': commandOrNA(values.installCommand),
    '{{MIGRATION_COMMAND}}': commandOrNA(values.migrationCommand),
    '{{MIGRATE_COMMAND}}': commandOrNA(values.migrationCommand),
    '{{DEV_COMMAND}}': commandOrNA(values.devCommand),
    '{{BUILD_COMMAND}}': commandOrNA(values.buildCommand),
    '{{TYPECHECK_COMMAND}}': commandOrNA(values.typecheckCommand),
    '{{TEST_COMMAND}}': commandOrNA(values.testCommand),
    '{{LINT_COMMAND}}': commandOrNA(values.lintCommand),
    '{{SEED_COMMAND}}': commandOrNA(values.seedCommand),
    '{{CACHE_QUEUE}}': 'N/A',
    '{{AUTH_STRATEGY}}': 'N/A',
    '{{EMAIL_PROVIDER}}': 'N/A',
    '{{STORAGE}}': 'N/A',
    '{{CLOUD_PROVIDER}}': 'N/A',
    '{{IAC_TOOL}}': 'N/A',
    '{{CICD_PLATFORM}}': 'GitHub Actions',
    '{{PM_TOOL}}': 'GitHub Projects',
    '{{LICENSE}}': 'UNLICENSED',
    '{{YEAR}}': new Date().getFullYear().toString(),
    '{{UNSUPPORTED_CAPABILITIES}}': unsupportedCapabilityNote(values),
  };

  let result = content;
  for (const [token, value] of Object.entries(tokenMap)) {
    result = result.split(token).join(value);
  }
  // Drop whole lines for capabilities declared `none` so no fenced command
  // block ever contains a non-command.
  result = result
    .split('\n')
    .filter((line) => !line.includes(OMIT_LINE))
    .join('\n');
  return result;
}

/**
 * Adopter-facing CLI guidance for the generated project.
 *
 * Generated rather than templated. The templates directory holds five
 * independent per-profile copies of every shipped document, so a templated
 * version would be five files to keep in step and five chances to drift. This
 * is also the only route that reaches BOTH `create` and `init` — and a template
 * docs directory is not in the package allowlist at all, so a document placed
 * there would never reach an adopter installing from npm.
 *
 * Written as an array of single-quoted lines so the markdown can use backticks
 * freely without escaping every one of them inside a template literal.
 */
const DOCTOR_GUIDE = [
  '# AI Scaffold — CLI Reference for This Project',
  '',
  'Generated by AI Scaffold. Safe to read, not worth editing: it is rewritten on',
  'every install and update.',
  '',
  '## Diagnosing This Installation',
  '',
  '`ais doctor` verifies what is actually true of this project, not what a config',
  'file declares. It is read-only and never changes repository or local settings.',
  '',
  '```bash',
  'ais doctor                 # this project',
  'ais doctor --json          # machine-readable, for CI',
  '```',
  '',
  'Alongside the local installation checks it reports **effective governance**:',
  'whether `main` and `dev` are really protected (merged across GitHub branch',
  'protection *and* rulesets, because a repository can use either or both),',
  'whether a status check is both required *and* observed reporting, whether',
  'administrators can bypass protection, and whether `.git/hooks/pre-commit` is',
  'really installed and executable rather than merely wired in',
  '`.claude/settings.json`.',
  '',
  '### Three states, not two',
  '',
  '| Output | Meaning | Counts as a failure? |',
  '|---|---|---|',
  '| `✓ [SEV]` | Verified good | no |',
  '| `✗ [SEV]` | Verified gap | yes |',
  '| `? [UNAVAILABLE]` | Verification was attempted and produced no evidence | **no** by default |',
  '',
  '`[UNAVAILABLE]` is not a skip and never a pass. Each one names the condition',
  'and the single action that would resolve it. `doctor` exits `0` when checks are',
  'unavailable and nothing failed: being unable to verify is an environment',
  'problem you may not control, while a detected gap is one you can fix.',
  '',
  '### Enforcing the remote checks in CI',
  '',
  '```bash',
  'ais doctor --require-remote            # unavailable GitHub checks now fail',
  'ais doctor --repo owner/name           # skip repository auto-detection',
  '```',
  '',
  '`--require-remote` turns an unavailable **GitHub** check into a failure, for',
  'pipelines where the GitHub CLI is installed and authenticated. It does not',
  'affect local checks that verified nothing. `--repo` overrides detection and',
  'lets `doctor` run outside a checkout.',
  '',
  'The GitHub checks authenticate through the `gh` CLI. This tool never accepts,',
  'stores, reads or logs a token, and issues only `gh api --method GET` and',
  '`gh repo view`.',
  '',
  '### What the unavailable reasons mean',
  '',
  '| Reason | Fix |',
  '|---|---|',
  '| GitHub CLI not installed | Install it: <https://cli.github.com> |',
  '| GitHub CLI not authenticated | `gh auth login` |',
  '| no GitHub repository configured | Add a GitHub remote, or pass `--repo owner/name` |',
  '| insufficient GitHub permission | Administrator bypass needs more access than the current token has; the other checks still answer |',
  '| GitHub API rate limit exhausted | Wait for the reset, or authenticate `gh` for a higher limit |',
  '| no merged pull request in the lookback window | Nothing to observe yet; the check reports this rather than claiming zero successful checks |',
  '| more evidence than the scan reads | The scan hit its page budget, so absence is not proven |',
  '| no git repository at the target | `git init`, so hook installation can be verified |',
  '',
  'A governed branch that does not exist here is excluded and named, not treated',
  'as a gap: a repository with `main` and no `dev` is not misconfigured.',
].join('\n');

export function buildScaffoldReadme(values) {
  const requirementsPath = values.requirementsPath || 'not linked yet';

  return `# AI Scaffold

This folder contains AI Scaffold's project-local operating context for ${values.displayName}.

## Installed Context

- Profile: ${values.profile}
- Project kind: ${values.projectType}
- Lifecycle stage: ${values.lifecycleStage}
- Data sensitivity: ${values.dataSensitivity}
- Compliance scope: ${formatCompliance(values.complianceScope)}

## Requirements Link

- Source: ${values.requirementsSource ?? 'create-later'}
- Path: ${requirementsPath}

AI work is strongest when every task links to a BRD, FRD, ticket, or acceptance
criteria document. If the path is not linked yet, update \`.ai-scaffold/context.md\`,
\`.claude/settings-overrides.json\`, and \`.claude/MEMORY.md\` before serious
feature work.

Use:

\`\`\`text
/start-task --spec <requirements-or-task-path>
\`\`\`

## Default Install Surface

The default install keeps scaffold-owned reference material small. Larger docs,
QA, UX, research, CI, and template packs should be added explicitly when needed.

See \`.ai-scaffold/context.md\` for the project setup context collected during
installation. Run \`ais doctor\` after changing scaffold settings.

See \`.ai-scaffold/cli-reference.md\` for what \`doctor\` checks, what
\`? [UNAVAILABLE]\` means, and how to enforce the GitHub checks in CI.
`;
}

/**
 * The doctor guidance, as its OWN generated file.
 *
 * It cannot live in `.ai-scaffold/README.md`: on `init` that path is already
 * taken by the namespaced project README template, and the template copy wins,
 * so `buildScaffoldReadme` never runs for an existing repository. Existing
 * repositories are precisely the population with real branch protection to
 * check, so putting the guidance there would miss the audience that needs it.
 * A distinct path under `.ai-scaffold/` is returned verbatim by
 * `resolveGeneratedTargetRel` on both install paths.
 */
export function buildCliReference() {
  return `${DOCTOR_GUIDE}\n`;
}

